  q.assert(detailById.get(q.P).images.length === 2 && [q.sourceA.answer.job_id,q.sourceB.answer.job_id,q.A,q.B]
    .every(id=>detailById.get(id).images.length === 1), 'actual owned outputs are not the expected six images');
  const a=detailById.get(q.A), b=detailById.get(q.B);
  q.assert(a.images[0].prompt === q.payloads.sourceA.prompt.replace('red hair','silver hair')
    && b.images[0].prompt === q.payloads.sourceB.prompt.replace('red hair','silver hair')
    && a.images[0].width === 256 && a.images[0].height === 256 && b.images[0].width === 384 && b.images[0].height === 256
    && a.images[0].seed === 9101 && b.images[0].seed === 9102 && a.images[0].steps === 1
    && b.images[0].steps === 100 && a.run_id === q.swap.actual.run_id
    && b.run_id === q.swap.actual.more[0].run_id && byId.get(q.A).swap === byId.get(q.B).swap,
    'actual completed split outcomes lost source text/seed/size/run identity');
  const all=await q.read('/api/gallery?all_models=true&limit=20');
  const current=all.items.filter(row=>row.model_id === loadedModel);
  const planted=all.items.filter(row=>row.model_id !== loadedModel).sort((a,b)=>a.id-b.id);
  q.assert(all.total === 8 && all.items.length === 8 && current.length === 6
    && JSON.stringify(planted) === q.planted, 'six owned current-model rows or untouched planted pair changed');
  q.assert(q.grants.length === 5 && q.grants.every(grant=>grant.seen === 1 && grant.forwarded && grant.done && grant.status === 200 && !grant.error)
    && q.swap.seen === 1 && q.swap.forwarded && q.swap.ready && q.swap.released && q.swap.delivered && !q.swap.error,
    'unused or unsettled exact generation/pause/resume/native Swap grants remain');
  q.assert(q.listGate.released && q.lists.every(list=>list.done && list.forwarded && !list.error)
    && q.previews.length > 0 && q.previews.every(preview=>preview.done && !preview.error),
    'gated ordinary lists or preview reads remain unsettled');
  q.assert(q.opens(q.P) === 1 && q.opens(q.B) === 1 && q.opens(q.A) === 1
    && q.opens(q.sourceA.answer.job_id) === 0 && q.opens(q.sourceB.answer.job_id) === 0
    && q.predecessorSettled && !q.predecessorError && q.streams.every(stream=>stream.source.readyState === 2), 'actual streams duplicated or remained active/unwatched receipts stranded');
  const backup=await q.read('/api/gallery/automatic-backup');
  q.assert(backup.enabled === false && backup.credential_configured === false
    && backup.credential_state === 'not_configured', 'backup became active');
  q.assert(q.forbidden.length === 0 && q.errors.length === 0 && !currentJob && !binMode && !sheetMode
    && !els.allModels.checked && queueCancelling.size === 0 && q.panel() === q.before
    && JSON.stringify(selectedIds()) === JSON.stringify(q.sourceIds) && selectAnchor === q.anchor,
    'final jobs/gates/queue/context/picks/composer are not clean');
  q.final={history:details.map(job=>({job_id:job.job_id,status:job.status,images:job.images.length,run_id:job.run_id})),
    ownedImages:current.map(row=>({id:row.id,job_id:row.job_id,run_id:row.run_id,prompt:row.prompt,width:row.width,height:row.height,seed:row.seed})),
    streams:q.streams.map(stream=>({id:stream.id,closed:stream.source.readyState === 2}))};
  return true;
})()
